def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = max((v for v in counts if v != bg), key=lambda v: counts[v])

    out = [[bg if v != color else color for v in row] for row in grid]

    # Fill dense rectangular regions of the principal foreground color.
    # This also handles rectangles joined together along a shared edge.
    marked = [[False] * w for _ in range(h)]
    for r1 in range(h):
        for r2 in range(r1, h):
            for c1 in range(w):
                for c2 in range(c1, w):
                    area = (r2-r1+1) * (c2-c1+1)
                    if area < 8:
                        continue
                    n = sum(grid[r][c] == color
                            for r in range(r1, r2+1)
                            for c in range(c1, c2+1))
                    if n / area >= 0.82:
                        for r in range(r1, r2+1):
                            for c in range(c1, c2+1):
                                marked[r][c] = True

    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = color
    return out
